import random, sys
sys.path.insert(0,'/workspace/project')
from modules import byte_program as bp
from modules.capture_audit import parse_requests, Budget, BudgetError

def build_node(data, rnd):
    """Random compressed representation of the same bytes."""
    if len(data) == 0:
        return bp.literal(b'')
    style = rnd.random()
    if len(data) < 3 or style < 0.35:
        return bp.literal(data)
    if style < 0.55:
        k = rnd.randrange(1, len(data))
        return bp.cat((build_node(data[:k], rnd), build_node(data[k:], rnd)))
    if style < 0.75:
        # find a repeated period
        for period in range(1, min(6, len(data))):
            if len(data) % period == 0:
                unit = data[:period]
                if unit * (len(data)//period) == data:
                    return bp.repeat(build_node(unit, rnd), len(data)//period)
        k = rnd.randrange(1, len(data))
        return bp.cat((build_node(data[:k], rnd), build_node(data[k:], rnd)))
    lo = rnd.randrange(0, len(data)); hi = rnd.randrange(lo, len(data))
    padded = data[:lo] + b'\0'*(hi-lo) + data[hi:]
    # embed as slice of a larger literal: keep it simple -> slice of cat
    inner = bp.cat((bp.literal(data[:lo]), bp.literal(b'\0'*(hi-lo)), bp.literal(data[hi:])))
    return bp.cut(inner, lo, hi) if False else bp.cut(bp.cat((bp.literal(b'PAD'), inner)), 3+lo, 3+hi)

def norm(reqs):
    return [{k:v for k,v in r.items() if not k.endswith('_bytes')} for r in reqs]

from diff_parse import rand_channel
bad = 0
for seed in range(3000):
    rnd = random.Random(seed)
    data = rand_channel(rnd)
    b1 = Budget(); b2 = Budget()
    try:
        r1, e1 = norm(parse_requests(bp.literal(data), b1)[0]), parse_requests(bp.literal(data), Budget())[1]
    except BudgetError:
        continue
    node = build_node(data, rnd)
    assert bytes(bp.read_bytes(node,0,node.n)) == data, ('node mismatch', seed)
    assert node.h == bp.literal(data).h, ('hash mismatch', seed, data)
    r2, e2 = parse_requests(node, b2)
    r2 = norm(r2)
    if r1 != r2 or e1 != e2:
        bad += 1
        if bad < 3:
            print('MISMATCH seed', seed, data)
            print(' lit', r1, e1)
            print(' cmp', r2, e2)
print('compressed-vs-literal parse OK, bad =', bad)
EOF
